  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {
101→        self.project.is_some()
102→    }
103→}
104→
105→/// Find the project root by walking up from current directory.
106→///
107→/// Looks for:
108→/// 1. `.bivvy` directory (primary indicator)
109→/// 2. `.git` directory (fallback)
110→///
111→/// # Returns
112→///
113→/// The path to the project root, or None if not found.
114→pub fn find_project_root(start: &Path) -> Option<PathBuf> {
115→    let mut current = start.to_path_buf();
116→
117→    loop {
118→        // Check for .bivvy directory
119→        if current.join(".bivvy").is_dir() {
120→            return Some(current);
121→        }
122→
123→        // Check for .git directory (fallback)
124→        if current.join(".git").exists() {
125→            return Some(current);
126→        }
127→
128→        // Move up one directory
129→        if !current.pop() {
130→            return None;
131→        }
132→    }
133→}
134→
135→/// Load a single config file and parse it into BivvyConfig.
136→///
137→/// # Errors
138→///
139→/// Returns `ConfigNotFound` if the file doesn't exist.
140→/// Returns `ConfigParseError` if the YAML is invalid.
141→pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
142→    let content = fs::read_to_string(path).map_err(|e| {
143→        if e.kind() == std::io::ErrorKind::NotFound {
144→            BivvyError::ConfigNotFound {
145→                path: path.to_path_buf(),
146→            }
147→        } else {
148→            BivvyError::Io(e)
149→        }
150→    })?;
151→
152→    parse_config(&content, path)
153→}
154→
155→/// Parse YAML content into BivvyConfig.
156→///
157→/// # Arguments
158→///
159→/// * `content` - The YAML content to parse
160→/// * `source_path` - Path for error reporting
161→pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
162→    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
163→        path: source_path.to_path_buf(),
164→        message: e.to_string(),
165→    })
166→}
167→
168→/// Load a config file as raw YAML Value (for merging).
169→///
170→/// Returns the raw serde_yaml::Value without deserializing into
171→/// BivvyConfig, which allows for deep merging before final parsing.
172→pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
173→    let content = fs::read_to_string(path).map_err(|e| {
174→        if e.kind() == std::io::ErrorKind::NotFound {
175→            BivvyError::ConfigNotFound {
176→                path: path.to_path_buf(),
177→            }
178→        } else {
179→            BivvyError::Io(e)
180→        }
181→    })?;
182→
183→    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
184→        path: path.to_path_buf(),
185→        message: e.to_string(),
186→    })
187→}
188→
189→/// Load and merge all config files for a project.
190→///
191→/// Discovers and merges configs in this order:
192→/// 1. Remote base configs (from `extends:`)
193→/// 2. User global config (`~/.bivvy/config.yml`)
194→/// 3. Project config (`.bivvy/config.yml`)
195→/// 4. Local overrides (`.bivvy/config.local.yml`)
196→///
197→/// # Errors
198→///
199→/// Returns `ConfigNotFound` if no project config exists.
200→/// Returns `ConfigParseError` if any config file is invalid.
201→pub fn load_merged_config(project_root: &Path) -> Result<BivvyConfig> {
202→    load_merged_config_with_resolver(project_root, &ExtendsResolver::default())
203→}
204→
205→/// Load and merge configs with a specific extends resolver.
206→///
207→/// This is the implementation behind `load_merged_config`, exposed
208→/// separately to allow injecting a custom resolver for testing.
209→pub fn load_merged_config_with_resolver(
210→    project_root: &Path,
211→    resolver: &ExtendsResolver,
212→) -> Result<BivvyConfig> {
213→    let paths = ConfigPaths::discover(project_root);
214→
215→    if !paths.has_project_config() {
216→        return Err(BivvyError::ConfigNotFound {
217→            path: project_root.join(".bivvy").join("config.yml"),
218→        });
219→    }
220→
221→    let mut configs = Vec::new();
222→
223→    // Load in merge order
224→    for path in paths.all_existing() {
225→        let value = load_config_value(path)?;
226→        configs.push(value);
227→    }
228→
229→    // Merge all configs
230→    let merged = merge_configs(&configs);
231→
232→    // Parse merged value into typed config
233→    let config: BivvyConfig =
234→        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
235→            path: project_root.join(".bivvy").join("config.yml"),
236→            message: format!("Failed to parse merged config: {}", e),
237→        })?;
238→
239→    // Resolve extends if present
240→    if config.extends.is_some() {
241→        let resolved = resolver.resolve(&config)?;
242→        Ok(resolved)
243→    } else {
244→        Ok(config)
245→    }
246→}
247→
248→/// Load config with optional path override.
249→///
250→/// If `config_override` is provided, loads only that file without merging.
251→/// Otherwise, discovers and merges all config files.
252→pub fn load_config(project_root: &Path, config_override: Option<&Path>) -> Result<BivvyConfig> {
253→    if let Some(override_path) = config_override {
254→        // Direct load of specified file, no merging
255→        load_config_file(override_path)
256→    } else {
257→        load_merged_config(project_root)
258→    }
259→}
