use crate::config::extends::ExtendsResolver;
use crate::config::merger::merge_configs;
use crate::config::schema::BivvyConfig;
use crate::error::{BivvyError, Result};
use std::fs;
use std::path::{Path, PathBuf};

/// Detect whether a file is TOML based on its extension.
fn is_toml(path: &Path) -> bool {
    path.extension().is_some_and(|ext| ext == "toml")
}

/// Convert a `toml::Value` into a `serde_yaml::Value` so that the existing
/// merge pipeline works unchanged regardless of the source format.
fn toml_to_yaml_value(tv: toml::Value) -> serde_yaml::Value {
    match tv {
        toml::Value::String(s) => serde_yaml::Value::String(s),
        toml::Value::Integer(i) => serde_yaml::Value::Number(serde_yaml::Number::from(i)),
        toml::Value::Float(f) => {
            serde_yaml::Value::Number(serde_yaml::Number::from(f))
        }
        toml::Value::Boolean(b) => serde_yaml::Value::Bool(b),
        toml::Value::Datetime(dt) => serde_yaml::Value::String(dt.to_string()),
        toml::Value::Array(arr) => {
            serde_yaml::Value::Sequence(arr.into_iter().map(toml_to_yaml_value).collect())
        }
        toml::Value::Table(table) => {
            let map = table
                .into_iter()
                .map(|(k, v)| (serde_yaml::Value::String(k), toml_to_yaml_value(v)))
                .collect();
            serde_yaml::Value::Mapping(map)
        }
    }
}

