            r#"
settings:
  default_output: quiet
"#,
        )
        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();

        assert_eq!(config.app_name, Some("TestApp".to_string()));
        assert_eq!(config.settings.default_output, OutputMode::Quiet);
